  (md5('schood-toefl-pb-plan:eight-week-standard')::uuid, 'eight-week-standard', 'balanced', 'Eight-Week Standard', 'A balanced 56-day plan for learners at band 3.5–4.5 aiming for 4.5–5. Three full mocks in the TOEFL simulator, two four-week repair cycles, every section in contact every week, and a final week built from the Final 14 Days guide.', 56, 58, 106, 'all', 'moderate', '{"format":"toefl-ibt-2026","score_scale":"1-6","weekly_hours":{"min":8,"max":12},"daily_routine":["15–20 minutes: one Complete the Words paragraph or ten Listen and Repeat sentences","40–50 minutes: priority-section drills","15–20 minutes: maintenance for another section (rotate)","10 minutes: error log"],"weekly_rhythm":["Two heavier days (timed sets or a mock)","Three focused drill days","One review day (60 minutes, error-log counts and plan)","One rest day"],"weeks":[{"week":1,"label":"Week 1 · Baseline and profile","phase":"Diagnose","hours":9,"focus":["Full mock baseline","Profile A–D","Error log"],"tasks":["Full mock 1 in the TOEFL simulator (full exam), real order, no pauses.","Review the mock and write section bands, timing notes and your profile (A–D) from the Band 4 to 5 Roadmap.","Set up the error log with the 14 categories and log every miss from the mock.","Read the Score Scale 2026 module and write your exact target: overall band, section minimums, deadline.","Two short drill sessions on the largest category.","Weekly review: choose priority section and maintenance section for weeks 2–4."],"modules":["toefl-essentials","score-scale-2026","score-goals-and-study-plans","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 1"},"checkpoint":{"measure":"Baseline bands and 30+ log entries","target":"Priority section chosen with evidence"}},{"week":2,"label":"Week 2 · Priority section foundations","phase":"Build","hours":9,"focus":["Priority section drills","Complete the Words routine","Build a Sentence accuracy"],"tasks":["Four sessions of priority-section drills matched to its largest category.","Daily Complete the Words paragraph using the five-step routine; log misses by type (SLOT, FAMILY, AGREE, PHRASE, SMALL, SPELL, VOCAB).","Two Build a Sentence sets in simulator practice; log every miss by sentence structure.","One listening session with reply-type labelling for Listen and Choose a Response.","One speaking session: Listen and Repeat exactness and one interview.","Weekly review: measure drill accuracy for the priority category."],"modules":["reading-complete-the-words","writing-build-a-sentence","listening-strategy","guide-complete-the-words-drills"],"guides":["guide-complete-the-words-drills"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Task-type sets"},"checkpoint":{"measure":"Priority drill accuracy measured twice","target":"Accuracy trend recorded (no change after two weeks means change the drill)"}},{"week":3,"label":"Week 3 · Timed sets and productive feedback","phase":"Build","hours":10,"focus":["Timed priority sets","Email frame","Interview frameworks"],"tasks":["Three timed sets of the priority section.","Two timed emails (7 minutes) and one discussion post (10 minutes) with the two-minute proofread.","Two interviews using the Recall, Reaction, Position and Proposal frameworks, recorded and self-scored.","Thought-group and stress routine on one model answer.","Maintenance: one reading or listening set.","Weekly review."],"modules":["writing-email","speaking-take-an-interview","guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"guides":["guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Timed sets"},"checkpoint":{"measure":"Two timed writing tasks reviewed line by line","target":"Every email bullet covered; proofread catches most errors"}},{"week":4,"label":"Week 4 · Section mock and first re-check","phase":"Check","hours":10,"focus":["Priority section mock","Review protocol","Plan cycle two"],"tasks":["Section mock of the priority section in simulator practice.","Full review with the 90-minute protocol; recount categories.","Two drill sessions on whatever is still largest.","One academic discussion post and one interview.","Choose the second priority section for weeks 5–7.","Weekly review."],"modules":["reading-daily-life-and-academic","writing-academic-discussion","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Section mock"},"checkpoint":{"measure":"Priority section band vs baseline","target":"At least half a band above baseline in the priority section, or a clear drop in its error count"}},{"week":5,"label":"Week 5 · Second priority","phase":"Build","hours":10,"focus":["Second priority drills","Maintain the first","Listening structure"],"tasks":["Four sessions on the second priority section.","Two short maintenance sessions for the first priority section.","Three academic talks with purpose-and-structure notes.","Ten Listen and Repeat sentences on three days.","One email to a new reader type (office or manager).","Weekly review."],"modules":["listening-strategy","speaking-listen-and-repeat","guide-interview-answer-frameworks"],"guides":["guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Second-priority sets"},"checkpoint":{"measure":"Error categories counted","target":"Total misses per set falling in both priority sections"}},{"week":6,"label":"Week 6 · Full mock 2 and re-profile","phase":"Check","hours":11,"focus":["Full mock 2","Re-profile","Adjust plan"],"tasks":["Full mock 2 in the TOEFL simulator under the same conditions as mock 1.","Review and compare with mock 1 section by section.","Re-check your profile; if it changed, change the priority for week 7.","Two drill sessions on the two largest categories.","One timed writing pair (email and discussion).","Weekly review."],"modules":["score-goals-and-study-plans","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 2"},"checkpoint":{"measure":"Full mock 2 bands","target":"Overall at least half a band above mock 1, or within half a band of target"}},{"week":7,"label":"Week 7 · Close the two biggest gaps","phase":"Repair","hours":10,"focus":["Two largest categories","Repeat-error rate","Final 14 Days start"],"tasks":["Start the Final 14 Days guide: run its Day 14 to Day 8 tasks this week.","Four drill sessions on the two largest categories from mock 2.","Redo ten old log entries without answers; count how many you now get right.","Reschedule decision by the end of the week if needed (ETS: at least four full days before the test).","Confirm score recipients.","Weekly review."],"modules":["test-day-guide","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 3 at the end of the week"},"checkpoint":{"measure":"Repeat-error rate on old log entries","target":"Most old entries now answered correctly"}},{"week":8,"label":"Week 8 · Final week and test","phase":"Perform","hours":8,"focus":["Final mock review","Logistics","Test-day routine"],"tasks":["Review full mock 3 and write the top-ten error list.","Run the Final 14 Days guide''s Day 6 to Day 1 tasks.","Home Edition: equipment check and room rehearsal; test center: route and 30-minute early arrival.","Light practice only in the last three days; no full mocks.","Test day: follow the routine and the report-or-cancel rule you wrote in advance."],"modules":["test-day-guide","retake-and-mybest-strategy","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Warm-up sets"},"checkpoint":{"measure":"Mock 3 bands and logistics checklist","target":"Decision: test as planned, or extend with the Twelve-Week Foundation or a priority plan"}}],"checkpoints":[{"week":1,"check":"Full mock 1","target_band":"Entry 3.5–4.5 overall"},{"week":4,"check":"Priority-section mock","target_band":"Priority section +0.5 over baseline"},{"week":6,"check":"Full mock 2","target_band":"Overall +0.5 over mock 1 or within 0.5 of target"},{"week":7,"check":"Full mock 3","target_band":"At target or within a quarter band"}],"decision_rules":["No movement in a priority section after two full mocks four weeks apart: re-label the last 30 log entries before changing anything else.","If one section drops while you push another, add two maintenance sessions a week for it.","If mock 2 shows Writing or Speaking at least half a band below Reading and Listening, switch weeks 7–8 to the Speaking and Writing Priority plan''s final weeks."],"simulator_cta":"https://toefl.schood.online/full-exam?source=playbook&plan=eight-week-standard","practice_cta":"https://toefl.schood.online/practice?source=playbook&plan=eight-week-standard"}'::jsonb, '{"band_entry_min":3.5,"band_entry_max":4.5,"band_target_min":4.5,"band_target_max":5,"cefr_entry":"B1–B2","cefr_target":"B2–C1","focus_sections":["reading","listening","writing","speaking"],"weekly_hours_min":8,"weekly_hours_max":12,"full_mocks":3,"recommended_for":"A test date about two months away and a gap of up to one band.","score_window_basis":"score_min/score_max are the ETS 0-120 comparison totals for band 3.5 (58+) and the top of band 5 (106); band windows are in band_*","guarantee":"none: practice plan, not a score prediction","seeded_by":"20261028101000_toefl_playbook_plan_templates","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-plan:four-week-sprint')::uuid, 'four-week-sprint', 'crash', 'Four-Week Sprint', 'A high-intensity 28-day plan for learners within about half a band of their target (entry band 4–5, aiming up to 5.5). Two full mocks in the TOEFL simulator, two repair cycles driven by the error log, and a compressed final week.', 28, 72, 113, 'all', 'high', '{"format":"toefl-ibt-2026","score_scale":"1-6","weekly_hours":{"min":10,"max":14},"daily_routine":["20 minutes: one Complete the Words paragraph or one Listen and Repeat set (alternate days)","45–60 minutes: priority-category drills from the error log","20–30 minutes: maintenance for one strong section","10 minutes: log every miss with a category and a fix"],"weeks":[{"week":1,"label":"Week 1 · Baseline and triage","phase":"Diagnose","hours":12,"focus":["Full mock baseline","Error log set-up","Priority one drills"],"tasks":["Day 1: full mock in the TOEFL simulator (full exam) at your test time of day, real section order, no pauses between sections.","Day 2: 90-minute review of the mock; record section bands and set up the error log with the 14 categories from the Band 4 to 5 Roadmap.","Days 3–4: 75 minutes a day on your largest error category, using the matching drill (Complete the Words, reply-type labelling, proofreading, or Listen and Repeat exactness).","Day 5: one timed email (7 minutes) and one academic discussion post (10 minutes), each with a two-minute proofread.","Day 6: ten Listen and Repeat sentences checked word by word, then one full four-question interview recorded and self-scored.","Day 7: weekly review: count categories, redo five old misses without answers, plan week 2."],"modules":["score-scale-2026","toefl-essentials","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 1"},"checkpoint":{"measure":"Baseline section bands and the overall band rounded to the nearest half; error log with 30+ entries","target":"Profile (A–D) identified and two priority categories chosen"}},{"week":2,"label":"Week 2 · Repair priority one","phase":"Repair","hours":13,"focus":["Priority one repair","Timed writing","Speaking accuracy"],"tasks":["Days 1–3: 60 minutes a day of priority-one drills; change the drill if accuracy has not moved by day 3.","Daily: one Complete the Words paragraph from the Complete the Words Drills guide, timed and logged.","Day 4: write one request to three readers (professor, office, classmate), then one timed email using the email frame.","Day 5: two interviews using the four answer frameworks; shrinking-timer routine on one question.","Day 6: section mock of the priority section in simulator practice, reviewed with the same protocol as a full mock.","Day 7: weekly review and plan; compare the section mock with the baseline band for that section."],"modules":["reading-complete-the-words","writing-email","speaking-take-an-interview","guide-complete-the-words-drills","guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"guides":["guide-complete-the-words-drills","guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Section mock of the priority section"},"checkpoint":{"measure":"Priority-section mock band compared with its baseline band; count of entries in the priority category","target":"Priority section at or above its baseline band and fewer priority-category misses than week 1"}},{"week":3,"label":"Week 3 · Full mock 2 and repair two","phase":"Repair","hours":13,"focus":["Full mock 2","Priority two repair","Reschedule decision"],"tasks":["Day 1: full mock 2 in the TOEFL simulator under the same conditions as mock 1.","Day 2: 90-minute review; compare both mocks section by section and recount the error categories.","Days 3–5: 60–75 minutes a day on the largest category from mock 2, plus 20 minutes of maintenance.","Day 5: decide whether to keep the test date; ETS requires rescheduling at least four full days before the test.","Day 6: one timed email, one discussion post, seven Listen and Repeat sentences and one interview.","Day 7: confirm free score recipients (the Bulletin deadline is 10 p.m. local test-center time the day before the test) and write your top-ten error list."],"modules":["score-goals-and-study-plans","listening-strategy","writing-academic-discussion","guide-band-4-to-5-roadmap","guide-band-5-to-6-roadmap"],"guides":["guide-band-4-to-5-roadmap","guide-band-5-to-6-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 2"},"checkpoint":{"measure":"Mock 2 section bands and overall band versus mock 1","target":"Overall at target or within half a band of it, with no section more than one band below the target"}},{"week":4,"label":"Week 4 · Final days and test","phase":"Perform","hours":8,"focus":["Light targeted practice","Logistics","Test-day routine"],"tasks":["Days 1–2: 60 minutes a day: one short set of each section plus repair of your top-ten list.","Day 3: Home Edition: equipment check on the same weekday and time as the test, room set-up rehearsal; test center: route and arrival time (30 minutes early).","Day 4: 30 minutes of light mixed practice; ID checked against your ETS account name.","Day before the test: 20-minute warm-up only, read the top-ten list, pack, sleep at the usual time.","Test day: follow the test-center or Home Edition routine from the Final 14 Days guide; decide report or cancel by the rule you wrote in advance."],"modules":["test-day-guide","retake-and-mybest-strategy","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Short warm-up sets only"},"checkpoint":{"measure":"Logistics checklist complete; top-ten error list written","target":"Test taken with the planned routine; report-or-cancel decision made by rule, not by mood"}}],"checkpoints":[{"week":1,"check":"Full mock 1 bands recorded","target_band":"Entry 4–5 overall"},{"week":2,"check":"Priority-section mock","target_band":"Priority section at or above baseline"},{"week":3,"check":"Full mock 2","target_band":"Within 0.5 of target overall"}],"decision_rules":["If mock 2 is more than half a band below target overall, consider rescheduling and switching to the Eight-Week Standard plan.","If a priority category has not shrunk after one week, change the drill rather than adding hours.","Never schedule a full mock in the last three days before the test."],"simulator_cta":"https://toefl.schood.online/full-exam?source=playbook&plan=four-week-sprint","practice_cta":"https://toefl.schood.online/practice?source=playbook&plan=four-week-sprint"}'::jsonb, '{"band_entry_min":4,"band_entry_max":5,"band_target_min":4.5,"band_target_max":5.5,"cefr_entry":"B2–C1","cefr_target":"B2–C1","focus_sections":["reading","listening","writing","speaking"],"weekly_hours_min":10,"weekly_hours_max":14,"full_mocks":2,"recommended_for":"A test date about four weeks away and a gap of half a band or less.","score_window_basis":"score_min/score_max are the ETS 0-120 comparison totals for band 4 (72+) and the top of band 5.5 (113); band windows are in band_*","guarantee":"none: practice plan, not a score prediction","seeded_by":"20261028101000_toefl_playbook_plan_templates","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-plan:reading-listening-priority')::uuid, 'reading-listening-priority', 'skill_recovery', 'Reading and Listening Priority', 'A 42-day recovery plan for learners whose Reading and/or Listening bands sit at least half a band below their Writing and Speaking (overall 3.5–5). Most hours go to Complete the Words, academic passages, campus listening and academic talks, with vocabulary in families and short productive maintenance.', 42, 58, 113, 'reading', 'moderate', '{"format":"toefl-ibt-2026","score_scale":"1-6","focus_sections":["reading","listening"],"weekly_hours":{"min":8,"max":11},"split":"About 70% Reading and Listening, 30% Writing and Speaking maintenance","daily_routine":["15 minutes: vocabulary in families with collocations (academic words)","20 minutes: one Complete the Words paragraph plus one Daily Life or academic reading set","20 minutes: one listening set (alternate short exchanges and academic talks)","10 minutes (alternate days): one Listen and Repeat set or one Build a Sentence set"],"weeks":[{"week":1,"label":"Week 1 · Baseline and receptive audit","phase":"Diagnose","hours":9,"focus":["Full mock baseline","Misses by task type","Early-stage accuracy"],"tasks":["Full mock 1 in the TOEFL simulator; record all four section bands.","Audit Reading misses by task type: Complete the Words, Read in Daily Life, Read an Academic Passage.","Audit Listening misses by task type: Choose a Response, Conversation, Announcement, Academic Talk.","Note where misses cluster in each section (early or late) because Reading and Listening are two-stage adaptive.","Set up the vocabulary notebook by word family.","Weekly review: choose the first focus (Reading or Listening) from the audit."],"modules":["score-scale-2026","reading-complete-the-words","listening-strategy","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 1"},"checkpoint":{"measure":"Receptive audit complete","target":"Gap between receptive and productive sections confirmed (0.5 band or more)"}},{"week":2,"label":"Week 2 · Complete the Words and word families","phase":"Repair","hours":10,"focus":["Five-step routine","Suffix families","Short-word traps"],"tasks":["One Complete the Words drill a day from the Complete the Words Drills guide, in level order, misses logged by type.","Study the suffix and small-word sections; make one family list per day from your misses.","Two Read in Daily Life sets; write the writer''s purpose before answering.","Two Listen and Choose a Response sets with reply-type labels.","One Build a Sentence set and one Listen and Repeat set for maintenance.","Weekly review."],"modules":["reading-complete-the-words","reading-daily-life-and-academic","guide-complete-the-words-drills"],"guides":["guide-complete-the-words-drills"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Reading task sets"},"checkpoint":{"measure":"Complete the Words accuracy per drill","target":"Level 1–2 drills at 9/10 or better"}},{"week":3,"label":"Week 3 · Academic passages and purpose","phase":"Repair","hours":10,"focus":["Paragraph purpose","Stance mapping","Inference questions"],"tasks":["Four academic passages: write one function label per paragraph before answering.","Stance mapping on two passages: author''s view, reported view or evidence.","Drills 8–10 (level 3) from the Complete the Words Drills guide.","Section mock: Reading in simulator practice; review it with the full protocol.","One email and one interview for maintenance.","Weekly review."],"modules":["reading-daily-life-and-academic","guide-complete-the-words-drills","guide-band-5-to-6-roadmap"],"guides":["guide-complete-the-words-drills","guide-band-5-to-6-roadmap"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Reading section mock"},"checkpoint":{"measure":"Reading section mock band","target":"Reading at least half a band above baseline, or R-purpose and R-infer entries halved"}},{"week":4,"label":"Week 4 · Campus listening and academic talks","phase":"Repair","hours":10,"focus":["Conversations and announcements","Purpose and structure in talks","Accent rotation"],"tasks":["Three conversation sets: predict the next action before the questions.","Three announcement sets: note the changed detail and the action required.","Four academic talks with two-word notes for purpose and structure; one play only.","Rotate accents: one session each of North American, British and Australian speakers.","Section mock: Listening in simulator practice; review it.","Weekly review."],"modules":["listening-strategy","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Listening section mock"},"checkpoint":{"measure":"Listening section mock band","target":"Listening at least half a band above baseline, or L-structure and L-detail entries halved"}},{"week":5,"label":"Week 5 · Full mock 2 and the hardest material","phase":"Check","hours":10,"focus":["Full mock 2","Receptive recount","Level 4 drills"],"tasks":["Full mock 2 in the TOEFL simulator.","Recount receptive error categories (R-form, R-vocab, R-purpose, R-infer, L-reply, L-detail, L-structure).","Drills 11–12 (level 4) from the Complete the Words Drills guide, timed.","Two sessions on the largest remaining category.","Check Writing and Speaking have not dropped; add a maintenance session if they have.","Weekly review; start the Final 14 Days guide if your test is two weeks away."],"modules":["score-goals-and-study-plans","guide-complete-the-words-drills","guide-final-14-days"],"guides":["guide-complete-the-words-drills","guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 2"},"checkpoint":{"measure":"Mock 2 bands for all four sections","target":"Gap between receptive and productive sections smaller than at baseline"}},{"week":6,"label":"Week 6 · Consolidate and perform","phase":"Perform","hours":8,"focus":["Mixed timed sets","Top-ten error list","Test-day routine"],"tasks":["Two mixed timed sets: one Reading and one Listening, with extra care on the first items.","Write the top-ten error list, weighted toward Reading and Listening.","Logistics: ID, recipients, equipment check (Home Edition) or route (test center).","Light practice only in the last three days.","Test day, or continue with the Eight-Week Standard plan if mock 2 showed the gap is still large."],"modules":["test-day-guide","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Mixed timed sets"},"checkpoint":{"measure":"Final timed sets reviewed","target":"No new error categories; early-item misses rare"}}],"checkpoints":[{"week":1,"check":"Full mock 1 and receptive audit","target_band":"Reading or Listening ≥ 0.5 below Writing/Speaking"},{"week":3,"check":"Reading section mock","target_band":"+0.5 over Reading baseline"},{"week":4,"check":"Listening section mock","target_band":"+0.5 over Listening baseline"},{"week":5,"check":"Full mock 2","target_band":"Receptive gap narrower than baseline"}],"decision_rules":["If R-vocab dominates after week 3, add 15 minutes a day of reading longer academic texts and record new words in families.","If misses cluster early in a section, slow the first items down slightly in every practice set.","If Writing or Speaking drops by half a band, add two maintenance sessions a week."],"simulator_cta":"https://toefl.schood.online/full-exam?source=playbook&plan=reading-listening-priority","practice_cta":"https://toefl.schood.online/practice?source=playbook&plan=reading-listening-priority"}'::jsonb, '{"band_entry_min":3.5,"band_entry_max":5,"band_target_min":4,"band_target_max":5.5,"cefr_entry":"B1–C1","cefr_target":"B2–C1","focus_sections":["reading","listening"],"primary_focus_note":"focus_section holds one value; this plan covers reading and listening (see focus_sections)","entry_rule":"Reading and/or Listening at least 0.5 band below Writing and Speaking","weekly_hours_min":8,"weekly_hours_max":11,"full_mocks":2,"recommended_for":"Profile B learners: productive skills strong, receptive skills weaker.","score_window_basis":"score_min/score_max are the ETS 0-120 comparison totals for band 3.5 (58+) and the top of band 5.5 (113); band windows are in band_*","guarantee":"none: practice plan, not a score prediction","seeded_by":"20261028101000_toefl_playbook_plan_templates","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-plan:speaking-writing-priority')::uuid, 'speaking-writing-priority', 'skill_recovery', 'Speaking and Writing Priority', 'A 42-day recovery plan for learners whose Writing and/or Speaking bands sit at least half a band below their Reading and Listening (overall 3.5–5). Most hours go to Build a Sentence, the email, the discussion post, Listen and Repeat and the interview, with Reading and Listening kept in short maintenance sessions.', 42, 58, 113, 'speaking', 'moderate', '{"format":"toefl-ibt-2026","score_scale":"1-6","focus_sections":["speaking","writing"],"weekly_hours":{"min":8,"max":11},"split":"About 70% Speaking and Writing, 30% Reading and Listening maintenance","daily_routine":["10 minutes: ten Listen and Repeat sentences, recorded and checked word by word","25–35 minutes: one timed writing task or one interview set","10 minutes: Build a Sentence items or a proofread of yesterday''s writing","15 minutes (alternate days): Reading or Listening maintenance set"],"weeks":[{"week":1,"label":"Week 1 · Baseline and productive audit","phase":"Diagnose","hours":9,"focus":["Full mock baseline","Writing and Speaking audit","Personal error list"],"tasks":["Full mock 1 in the TOEFL simulator; record all four section bands.","Audit Writing: Build a Sentence score, email bullets covered, discussion contribution, and every grammar error found.","Audit Speaking: Listen and Repeat sentences with any change, interview answers under about 35 seconds of content.","Write your personal top-five grammar errors on a card.","Remember the weight: Listen and Repeat is 35 of 55 raw Speaking points; Build a Sentence is 10 of 20 raw Writing points.","Weekly review: choose the first focus (Speaking or Writing) from the audit."],"modules":["score-scale-2026","writing-build-a-sentence","speaking-listen-and-repeat","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 1"},"checkpoint":{"measure":"Writing and Speaking audit complete","target":"Gap between productive and receptive sections confirmed (0.5 band or more)"}},{"week":2,"label":"Week 2 · Accuracy engines: Build a Sentence and Listen and Repeat","phase":"Repair","hours":10,"focus":["Build a Sentence by structure","Listen and Repeat exactness","Thought groups"],"tasks":["Three Build a Sentence sets; log each miss by structure (question order, relative clause, embedded question, passive).","Daily Listen and Repeat: ten sentences, one repetition each, function words and endings counted.","Thought-group routine: mark slashes and stress on five long sentences, repeat, record.","Two short Reading or Listening maintenance sets.","Weekly review: Build a Sentence accuracy and exact-repetition count."],"modules":["writing-build-a-sentence","speaking-listen-and-repeat","guide-interview-answer-frameworks"],"guides":["guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Build a Sentence and Listen and Repeat sets"},"checkpoint":{"measure":"Build a Sentence score and exact repetitions out of 10","target":"Both higher than the week 1 audit"}},{"week":3,"label":"Week 3 · The email and the interview","phase":"Repair","hours":10,"focus":["Email frame and register","Recall and Reaction frameworks","Proofreading order"],"tasks":["Three emails: one formal, one polite-efficient, one friendly, each in 7 minutes with the two-minute proofread.","Compare each email with the annotated models in the Email and Discussion Templates guide.","Two interviews focusing on the Recall and Reaction frameworks; record and self-score.","Shrinking-timer routine on two questions.","Section mock: Speaking in simulator practice; review.","Weekly review."],"modules":["writing-email","speaking-take-an-interview","guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"guides":["guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Speaking section mock"},"checkpoint":{"measure":"Speaking section mock band; emails with every bullet covered","target":"Speaking at or above baseline; all bullets covered in 3 of 3 emails"}},{"week":4,"label":"Week 4 · The discussion and opinion answers","phase":"Repair","hours":10,"focus":["Discussion frame","Position and Proposal frameworks","Band 5–6 language"],"tasks":["Three discussion posts in 10 minutes each; check that each one adds something new to the classmates'' posts.","Rewrite one sentence per post with a limiting clause or precise contrast.","Two interviews focusing on the Position and Proposal frameworks.","Stress and intonation routine: contrast stress and new-information stress.","Section mock: Writing in simulator practice; review.","Weekly review."],"modules":["writing-academic-discussion","speaking-take-an-interview","guide-email-and-discussion-templates","guide-interview-answer-frameworks","guide-band-5-to-6-roadmap"],"guides":["guide-email-and-discussion-templates","guide-interview-answer-frameworks","guide-band-5-to-6-roadmap"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Writing section mock"},"checkpoint":{"measure":"Writing section mock band","target":"Writing at least half a band above baseline, or errors-found-later count halved"}},{"week":5,"label":"Week 5 · Full mock 2 and fine-tuning","phase":"Check","hours":10,"focus":["Full mock 2","Productive error recount","Receptive maintenance"],"tasks":["Full mock 2 in the TOEFL simulator.","Recount productive error categories (W-grammar, W-word, W-task, S-exact, S-flow, S-develop).","Two sessions on the largest remaining category.","Check Reading and Listening have not dropped; add a maintenance session if they have.","Start the Final 14 Days guide if your test is two weeks away.","Weekly review."],"modules":["score-goals-and-study-plans","guide-band-4-to-5-roadmap","guide-final-14-days"],"guides":["guide-band-4-to-5-roadmap","guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 2"},"checkpoint":{"measure":"Mock 2 bands for all four sections","target":"Gap between productive and receptive sections smaller than at baseline"}},{"week":6,"label":"Week 6 · Consolidate and perform","phase":"Perform","hours":8,"focus":["Timed productive pairs","Top-ten error list","Test-day routine"],"tasks":["Two timed pairs: email plus discussion, and seven Listen and Repeat sentences plus one interview.","Write the top-ten error list, weighted toward Writing and Speaking.","Logistics: ID, recipients, equipment check (Home Edition) or route (test center).","Light practice only in the last three days.","Test day, or continue with the Eight-Week Standard plan if mock 2 showed the gap is still large."],"modules":["test-day-guide","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Timed productive pairs"},"checkpoint":{"measure":"Final timed pairs reviewed","target":"Every email bullet covered, every post adds a new point, Listen and Repeat mostly exact"}}],"checkpoints":[{"week":1,"check":"Full mock 1 and productive audit","target_band":"Writing or Speaking ≥ 0.5 below Reading/Listening"},{"week":3,"check":"Speaking section mock","target_band":"At or above Speaking baseline"},{"week":4,"check":"Writing section mock","target_band":"+0.5 over Writing baseline"},{"week":5,"check":"Full mock 2","target_band":"Productive gap narrower than baseline"}],"decision_rules":["If Listen and Repeat exact repetitions do not rise by week 3, slow down: repeat shorter sentences perfectly before longer ones.","If the same grammar errors keep appearing, proofread only for your personal top five until they disappear.","If Reading or Listening drops by half a band, add two maintenance sessions a week."],"simulator_cta":"https://toefl.schood.online/full-exam?source=playbook&plan=speaking-writing-priority","practice_cta":"https://toefl.schood.online/practice?source=playbook&plan=speaking-writing-priority"}'::jsonb, '{"band_entry_min":3.5,"band_entry_max":5,"band_target_min":4,"band_target_max":5.5,"cefr_entry":"B1–C1","cefr_target":"B2–C1","focus_sections":["speaking","writing"],"primary_focus_note":"focus_section holds one value; this plan covers speaking and writing (see focus_sections)","entry_rule":"Writing and/or Speaking at least 0.5 band below Reading and Listening","weekly_hours_min":8,"weekly_hours_max":11,"full_mocks":2,"recommended_for":"Profile A learners: receptive skills strong, productive skills weaker.","score_window_basis":"score_min/score_max are the ETS 0-120 comparison totals for band 3.5 (58+) and the top of band 5.5 (113); band windows are in band_*","guarantee":"none: practice plan, not a score prediction","seeded_by":"20261028101000_toefl_playbook_plan_templates","content_revision":"toefl-2026-premium-v1"}'::jsonb),
  (md5('schood-toefl-pb-plan:twelve-week-foundation')::uuid, 'twelve-week-foundation', 'improvement', 'Twelve-Week Foundation', 'A steady 84-day plan for learners at band 2.5–3.5 (A2–B1) building toward 3.5–4.5 (B1–B2). Foundations first (vocabulary in families, sentence grammar, everyday reading and listening, clear repetition), then task skills, then test conditions. Three full mocks in the TOEFL simulator.', 84, 34, 94, 'all', 'steady', '{"format":"toefl-ibt-2026","score_scale":"1-6","weekly_hours":{"min":6,"max":9},"daily_routine":["15 minutes: vocabulary in word families with a collocation for each word","20 minutes: one skill block (reading, listening or grammar) at your level","10 minutes: speaking aloud (repetition or a short answer), recorded","5 minutes: error log"],"weeks":[{"week":1,"label":"Week 1 · Baseline and the format","phase":"Foundation","hours":7,"focus":["Full mock baseline","Learn the format","Start the vocabulary notebook"],"tasks":["Read TOEFL Essentials and Score Scale 2026 so you know every task type and how bands work.","Full mock 1 in the TOEFL simulator; do not worry about the score, it is your starting point.","Set up the error log and a vocabulary notebook organised by word family (noun, verb, adjective, adverb).","Two Read in Daily Life sets: notices, emails, schedules.","Weekly review: write your target and deadline."],"modules":["toefl-essentials","score-scale-2026","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 1"},"checkpoint":{"measure":"Baseline bands recorded","target":"Every task type recognised by name"}},{"week":2,"label":"Week 2 · Sentence grammar for Build a Sentence","phase":"Foundation","hours":7,"focus":["Word order","Questions and relative clauses","Everyday reading"],"tasks":["Four short grammar sessions: statement and question word order, relative clauses with who/which/that, embedded questions.","Two Build a Sentence sets in simulator practice; log each miss by structure.","Three Read in Daily Life texts; write the purpose of each in one sentence before answering.","Daily vocabulary families (10 words a day).","Weekly review."],"modules":["writing-build-a-sentence","reading-daily-life-and-academic"],"guides":[],"simulator":{"url":"https://toefl.schood.online/practice","action":"Build a Sentence sets"},"checkpoint":{"measure":"Build a Sentence accuracy on two sets","target":"Accuracy trend recorded"}},{"week":3,"label":"Week 3 · Everyday listening","phase":"Foundation","hours":7,"focus":["Listen and Choose a Response","Short conversations","Clear repetition"],"tasks":["Four sessions of Listen and Choose a Response; label the reply type after each item.","Two short conversation sets; predict what the speakers will do next.","Daily: five Listen and Repeat sentences, short ones, recorded and checked.","Daily vocabulary families.","Weekly review."],"modules":["listening-strategy","speaking-listen-and-repeat"],"guides":[],"simulator":{"url":"https://toefl.schood.online/practice","action":"Listening sets"},"checkpoint":{"measure":"Reply-type accuracy","target":"Most common reply types recognised"}},{"week":4,"label":"Week 4 · Word families and Complete the Words","phase":"Foundation","hours":8,"focus":["Suffixes and endings","Complete the Words level 1","Section check"],"tasks":["Study the suffix table in the Complete the Words Drills guide; make one family list per day.","Drills 1–3 (level 1) from the Complete the Words Drills guide, one per day, with misses logged by type.","Section mock: Reading in simulator practice; review it.","Two speaking sessions: repetition plus one Recall interview answer.","Weekly review."],"modules":["reading-complete-the-words","guide-complete-the-words-drills"],"guides":["guide-complete-the-words-drills"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Reading section mock"},"checkpoint":{"measure":"Reading section mock band vs baseline","target":"Level 1 drills at 8/10 or better"}},{"week":5,"label":"Week 5 · First emails","phase":"Task skills","hours":8,"focus":["Email frame","Register","Functions bank"],"tasks":["Learn the five-move email frame and the register examples.","Write three emails without time pressure, one each to a professor, an office and a friend.","Write one email in 7 minutes; proofread with the checklist.","Two listening sessions: announcements.","Weekly review."],"modules":["writing-email","guide-email-and-discussion-templates"],"guides":["guide-email-and-discussion-templates"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Write an Email"},"checkpoint":{"measure":"Timed email reviewed","target":"All bullets covered in 7 minutes"}},{"week":6,"label":"Week 6 · Full mock 2","phase":"Check","hours":8,"focus":["Full mock 2","Compare with baseline","Re-plan"],"tasks":["Full mock 2 in the TOEFL simulator.","Review and compare with mock 1; count error categories.","Choose the two weakest areas for weeks 7–10.","Two drill sessions on the weakest area.","Weekly review."],"modules":["score-goals-and-study-plans","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 2"},"checkpoint":{"measure":"Full mock 2 bands","target":"Overall at least half a band above mock 1"}},{"week":7,"label":"Week 7 · Academic reading","phase":"Task skills","hours":8,"focus":["Read an Academic Passage","Purpose of paragraphs","Level 2 drills"],"tasks":["Three academic passages; write one line per paragraph on what the paragraph is for.","Drills 4–5 (level 2) from the Complete the Words Drills guide.","Two interview sessions using the Reaction framework.","Daily vocabulary families with academic words.","Weekly review."],"modules":["reading-daily-life-and-academic","reading-complete-the-words","guide-complete-the-words-drills","guide-interview-answer-frameworks"],"guides":["guide-complete-the-words-drills","guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Academic passage sets"},"checkpoint":{"measure":"Accuracy on purpose questions","target":"Fewer R-purpose entries than week 6"}},{"week":8,"label":"Week 8 · Academic listening and the discussion post","phase":"Task skills","hours":8,"focus":["Academic talks","Discussion frame","Thought groups"],"tasks":["Three academic talks; note purpose and structure while listening.","Learn the discussion frame; write two posts without time pressure, then one in 10 minutes.","Thought-group routine on two model answers.","Drills 6–7 (level 2) from the Complete the Words Drills guide.","Weekly review."],"modules":["listening-strategy","writing-academic-discussion","guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"guides":["guide-email-and-discussion-templates","guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Academic talk and discussion sets"},"checkpoint":{"measure":"Timed discussion post reviewed","target":"Position, reason, example and engagement present; 100+ words"}},{"week":9,"label":"Week 9 · Speaking under time","phase":"Task skills","hours":8,"focus":["Four interview frameworks","Shrinking timer","Longer repetitions"],"tasks":["Two full interviews using all four frameworks, recorded and self-scored.","Shrinking-timer routine on three questions.","Ten longer Listen and Repeat sentences on three days, checked word by word.","Section mock: Speaking in simulator practice; review it.","Weekly review."],"modules":["speaking-take-an-interview","speaking-listen-and-repeat","guide-interview-answer-frameworks"],"guides":["guide-interview-answer-frameworks"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Speaking section mock"},"checkpoint":{"measure":"Speaking section mock band","target":"Answers reach about 40 seconds with a direct first sentence"}},{"week":10,"label":"Week 10 · Mixed timed sets","phase":"Test conditions","hours":9,"focus":["Timed sets in every section","Two weakest areas","Proofreading"],"tasks":["One timed set of each section on separate days.","Two drill sessions on the two weakest areas from mock 2.","One timed email and one timed discussion with the two-minute proofread.","Redo ten old log entries without answers.","Weekly review."],"modules":["writing-email","writing-academic-discussion","guide-band-4-to-5-roadmap"],"guides":["guide-band-4-to-5-roadmap"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Timed sets"},"checkpoint":{"measure":"Repeat-error rate on old entries","target":"Most old entries now correct"}},{"week":11,"label":"Week 11 · Full mock 3 and the final fortnight","phase":"Test conditions","hours":9,"focus":["Full mock 3","Final 14 Days, days 14–8","Reschedule decision"],"tasks":["Start the Final 14 Days guide: full mock 3 on its Day 14, review on Day 13.","Run its repair days (Days 12–8) using mock 3''s largest categories.","Decide whether to keep the test date (ETS: reschedule at least four full days before).","Home Edition: equipment check at the same weekday and time as the test.","Weekly review."],"modules":["test-day-guide","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/full-exam","action":"Full mock 3"},"checkpoint":{"measure":"Full mock 3 bands","target":"At target or within half a band of it"}},{"week":12,"label":"Week 12 · Final week and test","phase":"Perform","hours":7,"focus":["Final 14 Days, days 7–1","Logistics","Test-day routine"],"tasks":["Follow the Final 14 Days guide from Day 7 to Day 1 (replace its full mock 2 with a section mock if you are tired).","Confirm score recipients before 10 p.m. local test-center time on the day before the test.","Write your top-ten error list and read it on the last day.","Test day: follow the test-center or Home Edition routine."],"modules":["test-day-guide","retake-and-mybest-strategy","guide-final-14-days"],"guides":["guide-final-14-days"],"simulator":{"url":"https://toefl.schood.online/practice","action":"Warm-up sets"},"checkpoint":{"measure":"Logistics checklist","target":"Test taken with the planned routine"}}],"checkpoints":[{"week":1,"check":"Full mock 1","target_band":"Entry 2.5–3.5 overall"},{"week":6,"check":"Full mock 2","target_band":"+0.5 over mock 1"},{"week":11,"check":"Full mock 3","target_band":"Target 3.5–4.5 or within 0.5"}],"decision_rules":["If mock 2 shows no movement, spend weeks 7–8 on vocabulary families and sentence grammar before task skills.","If one section is a full band below the others at mock 2, move to the matching priority plan for weeks 7–12.","Keep at least one rest day every week; this plan is designed to be sustainable."],"simulator_cta":"https://toefl.schood.online/full-exam?source=playbook&plan=twelve-week-foundation","practice_cta":"https://toefl.schood.online/practice?source=playbook&plan=twelve-week-foundation"}'::jsonb, '{"band_entry_min":2.5,"band_entry_max":3.5,"band_target_min":3.5,"band_target_max":4.5,"cefr_entry":"A2–B1","cefr_target":"B1–B2","focus_sections":["reading","listening","writing","speaking"],"weekly_hours_min":6,"weekly_hours_max":9,"full_mocks":3,"recommended_for":"A test date about three months away, or learners who found most task types hard in their first mock.","score_window_basis":"score_min/score_max are the ETS 0-120 comparison totals for band 2.5 (34+) and the top of band 4.5 (94); band windows are in band_*","guarantee":"none: practice plan, not a score prediction","seeded_by":"20261028101000_toefl_playbook_plan_templates","content_revision":"toefl-2026-premium-v1"}'::jsonb)
) as v(id, slug, plan_type, title, summary, duration_days, score_min, score_max, focus_section, intensity, schedule_json, metadata)
